krpano.action:
set(era_lay_on_ti, true);
set(era_lay_on_ht, true);
set(era_lay_on_dl, true);
set(era_lay_on_sp, true);
set(era_lay_open,  true);
if(device.mobile, set(era_lay_open, false); );

set(era_lay_acc,     0x9BDC4C);
set(era_lay_cpanel,  0x0E2821);
set(era_lay_cborder, 0xCBF0D6);
set(era_lay_cmuted,  0x83A08D);

set(era_lay_r, '');
if(bty == 'h', set(era_lay_r, 'ti'); );
if(bty == 'p', set(era_lay_r, 'ti'); );
if(bty == 'r', set(era_lay_r, 'ht'); );
if(bty == 'c', set(era_lay_r, 'ht'); );
if(bty == 'v',
  set(era_lay_r, 'dl');
  set(btl, get(hotspot[calc('poi_board_' + hp2)].p_title));
  set(bpos, -1); indexoftxt(bpos, get(btl), 'BAY');      if(bpos GE 0, set(era_lay_r, 'ht'); );
  set(bpos, -1); indexoftxt(bpos, get(btl), 'GIAO CAO'); if(bpos GE 0, set(era_lay_r, 'ht'); );
  set(bpos, -1); indexoftxt(bpos, get(btl), 'QL20');     if(bpos GE 0, set(era_lay_r, 'ht'); );
);

set(era_lay_n_ti, 0);
set(era_lay_n_ht, 0);
set(era_lay_n_dl, 0);
set(era_lay_n_sp, 0);

for(set(i, 0), i LT hotspot.count, inc(i),
  set(hlay, '');
  set(hcnt, false);

  if(hotspot[get(i)].islot == true,
    set(hlay, 'sp');
    set(hcnt, true);
  );

  if(hlay == '',
    set(hp0, ''); set(hp1, ''); set(hp2, '');
    txtsplit(get(hotspot[get(i)].name), '_', hp0, hp1, hp2);
    if(hp0 == 'poi',
      if(hp1 != '',
        set(bty, get(hotspot[calc('poi_board_' + hp2)].p_type));
        era_lay_map();
        set(hlay, get(era_lay_r));
        if(hp1 == 'board', set(hcnt, true); );
      );
    );
  );

  if(hlay != '',
    set(von, false);
    if(hlay == 'ti', copy(von, era_lay_on_ti); if(hcnt == true, inc(era_lay_n_ti); ); );
    if(hlay == 'ht', copy(von, era_lay_on_ht); if(hcnt == true, inc(era_lay_n_ht); ); );
    if(hlay == 'dl', copy(von, era_lay_on_dl); if(hcnt == true, inc(era_lay_n_dl); ); );
    if(hlay == 'sp', copy(von, era_lay_on_sp); if(hcnt == true, inc(era_lay_n_sp); ); );

    if(von,
      if(hotspot[get(i)].lay_hid == true,
        set(hotspot[get(i)].visible, true);
        set(hotspot[get(i)].lay_hid, false);
      );
    ,
      if(hotspot[get(i)].visible == true,
        set(hotspot[get(i)].visible, false);
        set(hotspot[get(i)].lay_hid, true);
      );
    );
  );
);

era_layers_paint();

addlayer(era_lay_hit_%1);
set(layer[era_lay_hit_%1].type, text); set(layer[era_lay_hit_%1].align, lefttop); set(layer[era_lay_hit_%1].edge, lefttop);
set(layer[era_lay_hit_%1].x, 24); set(layer[era_lay_hit_%1].y, %2); set(layer[era_lay_hit_%1].width, 198); set(layer[era_lay_hit_%1].height, 34);
set(layer[era_lay_hit_%1].bg, true); set(layer[era_lay_hit_%1].bgcolor, get(era_lay_acc)); set(layer[era_lay_hit_%1].bgalpha, 0.14); set(layer[era_lay_hit_%1].bgroundedge, 10);
set(layer[era_lay_hit_%1].handcursor, true); set(layer[era_lay_hit_%1].onclick, 'era_layers_toggle(%1)');
set(layer[era_lay_hit_%1].zorder, 220); set(layer[era_lay_hit_%1].keep, true); set(layer[era_lay_hit_%1].visible, true);

addlayer(era_lay_tx_%1);
set(layer[era_lay_tx_%1].type, text); set(layer[era_lay_tx_%1].align, lefttop); set(layer[era_lay_tx_%1].edge, lefttop);
set(layer[era_lay_tx_%1].x, 38); set(layer[era_lay_tx_%1].y, calc(%2 + 8)); set(layer[era_lay_tx_%1].width, 132); set(layer[era_lay_tx_%1].height, 18);
set(layer[era_lay_tx_%1].bg, false); set(layer[era_lay_tx_%1].enabled, false); set(layer[era_lay_tx_%1].vcenter, true);
set(layer[era_lay_tx_%1].css, 'color:#EDF8EF; font-family:Inter, Arial, sans-serif; font-size:12.5px; font-weight:600; white-space:nowrap;');
set(layer[era_lay_tx_%1].html, %3);
set(layer[era_lay_tx_%1].zorder, 222); set(layer[era_lay_tx_%1].keep, true); set(layer[era_lay_tx_%1].visible, true);

addlayer(era_lay_tr_%1);
set(layer[era_lay_tr_%1].type, text); set(layer[era_lay_tr_%1].align, lefttop); set(layer[era_lay_tr_%1].edge, lefttop);
set(layer[era_lay_tr_%1].x, 180); set(layer[era_lay_tr_%1].y, calc(%2 + 9)); set(layer[era_lay_tr_%1].width, 32); set(layer[era_lay_tr_%1].height, 16);
set(layer[era_lay_tr_%1].bg, true); set(layer[era_lay_tr_%1].bgcolor, get(era_lay_acc)); set(layer[era_lay_tr_%1].bgalpha, 0.95); set(layer[era_lay_tr_%1].bgroundedge, 8);
set(layer[era_lay_tr_%1].enabled, false);
set(layer[era_lay_tr_%1].zorder, 222); set(layer[era_lay_tr_%1].keep, true); set(layer[era_lay_tr_%1].visible, true);

addlayer(era_lay_kn_%1);
set(layer[era_lay_kn_%1].type, text); set(layer[era_lay_kn_%1].align, lefttop); set(layer[era_lay_kn_%1].edge, lefttop);
set(layer[era_lay_kn_%1].x, 198); set(layer[era_lay_kn_%1].y, calc(%2 + 11)); set(layer[era_lay_kn_%1].width, 12); set(layer[era_lay_kn_%1].height, 12);
set(layer[era_lay_kn_%1].bg, true); set(layer[era_lay_kn_%1].bgcolor, 0xFFFFFF); set(layer[era_lay_kn_%1].bgroundedge, 6);
set(layer[era_lay_kn_%1].bgshadow, '0 1 3 0x000000 0.45');
set(layer[era_lay_kn_%1].enabled, false);
set(layer[era_lay_kn_%1].zorder, 223); set(layer[era_lay_kn_%1].keep, true); set(layer[era_lay_kn_%1].visible, true);

era_layers_cfg();

addlayer(era_lay_bg);
set(layer[era_lay_bg].type, text); set(layer[era_lay_bg].align, lefttop); set(layer[era_lay_bg].edge, lefttop);
set(layer[era_lay_bg].x, 16); set(layer[era_lay_bg].y, 16); set(layer[era_lay_bg].width, 214); set(layer[era_lay_bg].height, 218);
set(layer[era_lay_bg].bg, true); set(layer[era_lay_bg].bgcolor, get(era_lay_cpanel)); set(layer[era_lay_bg].bgalpha, 0.82); set(layer[era_lay_bg].bgroundedge, 14);
set(layer[era_lay_bg].borderwidth, 1); set(layer[era_lay_bg].bordercolor, get(era_lay_cborder)); set(layer[era_lay_bg].borderalpha, 0.18);
set(layer[era_lay_bg].bgshadow, '0 4 18 0x000000 0.35');
set(layer[era_lay_bg].enabled, false);
set(layer[era_lay_bg].zorder, 218); set(layer[era_lay_bg].keep, true); set(layer[era_lay_bg].visible, true);

addlayer(era_lay_ttl);
set(layer[era_lay_ttl].type, text); set(layer[era_lay_ttl].align, lefttop); set(layer[era_lay_ttl].edge, lefttop);
set(layer[era_lay_ttl].x, 34); set(layer[era_lay_ttl].y, 26); set(layer[era_lay_ttl].width, 150); set(layer[era_lay_ttl].height, 18);
set(layer[era_lay_ttl].bg, false); set(layer[era_lay_ttl].enabled, false); set(layer[era_lay_ttl].vcenter, true);
set(layer[era_lay_ttl].css, 'color:#BAD8C3; font-family:Inter, Arial, sans-serif; font-size:11px; font-weight:700; letter-spacing:1.2px;');
set(layer[era_lay_ttl].html, 'LỚP HIỂN THỊ');
set(layer[era_lay_ttl].zorder, 222); set(layer[era_lay_ttl].keep, true); set(layer[era_lay_ttl].visible, true);

addlayer(era_lay_chev);
set(layer[era_lay_chev].type, text); set(layer[era_lay_chev].align, lefttop); set(layer[era_lay_chev].edge, lefttop);
set(layer[era_lay_chev].x, 186); set(layer[era_lay_chev].y, 24); set(layer[era_lay_chev].width, 28); set(layer[era_lay_chev].height, 22);
set(layer[era_lay_chev].bg, true); set(layer[era_lay_chev].bgcolor, get(era_lay_acc)); set(layer[era_lay_chev].bgalpha, 0.18); set(layer[era_lay_chev].bgroundedge, 6);
set(layer[era_lay_chev].vcenter, true); set(layer[era_lay_chev].handcursor, true);
set(layer[era_lay_chev].onclick, 'era_layers_fold()');
set(layer[era_lay_chev].css, 'color:#DCEFDA; font-family:Inter, Arial, sans-serif; font-size:12px; text-align:center;');
set(layer[era_lay_chev].html, '▾');
set(layer[era_lay_chev].zorder, 224); set(layer[era_lay_chev].keep, true); set(layer[era_lay_chev].visible, true);

era_lay_mkrow(1,  58, 'Tiện ích');
era_lay_mkrow(2,  96, 'Hạ tầng');
era_lay_mkrow(3, 134, 'Danh lam');
era_lay_mkrow(4, 172, 'Sản phẩm');

era_layers_fold_paint();

set(vtxt, ''); txtadd(vtxt, %4); txtadd(vtxt, get(vtxt), '  ·  '); txtadd(vtxt, get(vtxt), %3);
set(layer[era_lay_tx_%1].html, get(vtxt));

if(%2,
  set(layer[era_lay_hit_%1].bgalpha, 0.16);
  set(layer[era_lay_tr_%1].bgcolor, get(era_lay_acc));   set(layer[era_lay_tr_%1].bgalpha, 0.95);
  set(layer[era_lay_kn_%1].x, 198);
  set(layer[era_lay_tx_%1].css, 'color:#EDF8EF; font-family:Inter, Arial, sans-serif; font-size:12.5px; font-weight:600; white-space:nowrap;');
,
  set(layer[era_lay_hit_%1].bgalpha, 0.05);
  set(layer[era_lay_tr_%1].bgcolor, get(era_lay_cmuted)); set(layer[era_lay_tr_%1].bgalpha, 0.45);
  set(layer[era_lay_kn_%1].x, 182);
  set(layer[era_lay_tx_%1].css, 'color:#83A08D; font-family:Inter, Arial, sans-serif; font-size:12.5px; font-weight:500; white-space:nowrap;');
);

if(%3 == 0,
  set(layer[era_lay_hit_%1].alpha, 0.35); set(layer[era_lay_hit_%1].handcursor, false); set(layer[era_lay_hit_%1].enabled, false);
  set(layer[era_lay_tx_%1].alpha, 0.35);
  set(layer[era_lay_tr_%1].alpha, 0.35);  set(layer[era_lay_kn_%1].alpha, 0.35);
,
  set(layer[era_lay_hit_%1].alpha, 1); set(layer[era_lay_hit_%1].handcursor, true); set(layer[era_lay_hit_%1].enabled, true);
  set(layer[era_lay_tx_%1].alpha, 1);
  set(layer[era_lay_tr_%1].alpha, 1);  set(layer[era_lay_kn_%1].alpha, 1);
);

era_lay_paintrow(1, get(era_lay_on_ti), get(era_lay_n_ti), 'Tiện ích');
era_lay_paintrow(2, get(era_lay_on_ht), get(era_lay_n_ht), 'Hạ tầng');
era_lay_paintrow(3, get(era_lay_on_dl), get(era_lay_n_dl), 'Danh lam');
era_lay_paintrow(4, get(era_lay_on_sp), get(era_lay_n_sp), 'Sản phẩm');

set(era_lay_tot, calc(era_lay_n_ti + era_lay_n_ht + era_lay_n_dl + era_lay_n_sp));
if(era_lay_tot == 0, era_layers_show(false); , era_layers_show(true); );

set(layer[era_lay_bg].visible,   %1);
set(layer[era_lay_ttl].visible,  %1);
set(layer[era_lay_chev].visible, %1);
if(%1, era_layers_fold_paint(); , era_lay_rows_show(false); );

set(layer[era_lay_hit_1].visible, %1); set(layer[era_lay_tx_1].visible, %1); set(layer[era_lay_tr_1].visible, %1); set(layer[era_lay_kn_1].visible, %1);
set(layer[era_lay_hit_2].visible, %1); set(layer[era_lay_tx_2].visible, %1); set(layer[era_lay_tr_2].visible, %1); set(layer[era_lay_kn_2].visible, %1);
set(layer[era_lay_hit_3].visible, %1); set(layer[era_lay_tx_3].visible, %1); set(layer[era_lay_tr_3].visible, %1); set(layer[era_lay_kn_3].visible, %1);
set(layer[era_lay_hit_4].visible, %1); set(layer[era_lay_tx_4].visible, %1); set(layer[era_lay_tr_4].visible, %1); set(layer[era_lay_kn_4].visible, %1);

if(era_lay_open,
  set(layer[era_lay_bg].height, 218);
  set(layer[era_lay_chev].html, '▾');
  era_lay_rows_show(true);
,
  set(layer[era_lay_bg].height, 38);
  set(layer[era_lay_chev].html, '▸');
  era_lay_rows_show(false);
);

if(%1 == 1, set(era_lay_on_ti, calc(!era_lay_on_ti)); );
if(%1 == 2, set(era_lay_on_ht, calc(!era_lay_on_ht)); );
if(%1 == 3, set(era_lay_on_dl, calc(!era_lay_on_dl)); );
if(%1 == 4, set(era_lay_on_sp, calc(!era_lay_on_sp)); );
era_layers_apply();
